// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
        GlpManagerMock gm = new GlpManagerMock();
        c.initialize(
            IERC20(address(new Dummy())),
            IERC20(address(new Dummy())),
            IRewardRouterV2(address(new Dummy())),
            IGlpManager(address(gm)),
            address(new Dummy()),
            address(0xdead)
        );
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != c.keeper());
        vm.warp(1_000_000);
        vm.prank(caller);
        bool ok;
        try c.executeBatchDeposit() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "non-keeper must not be able to executeBatchDeposit");
    }
}

contract Dummy {
    fallback() external payable {}
}

contract GlpManagerMock {
    function vault() external pure returns (address) {
        return address(0x1);
    }
}
